362	    }, [
363	        StyleUtils,
364	        avoidKeyboard,
365	        insets,
366	        isUsingEdgeToEdgeMode,
367	        keyboardStateContextValue.isKeyboardActive,
368	        modalContainerStyle,
369	        shouldAddBottomSafeAreaMargin,
370	        shouldAddBottomSafeAreaPadding,
371	        shouldAddTopSafeAreaMargin,
372	        shouldAddTopSafeAreaPadding,
373	        shouldUseModalPaddingStyle,
374	    ]);
375	
376	    const modalContextValue = useMemo(
377	        () => ({
378	            activeModalType: isVisible ? type : undefined,
379	            default: false,
380	        }),
381	        [isVisible, type],
382	    );
383	
384	    const animationInProps = useMemo(() => {
385	        // disableAnimationIn applies only to legacy modals. This should be removed once we fully migrate to `reanimated-modal`.
