431	                        onBackButtonPress={closeTop}
432	                        onModalShow={handleShowModal}
433	                        propagateSwipe={propagateSwipe}
434	                        onModalHide={hideModal}
435	                        onModalWillShow={() => {
436	                            saveFocusState();
437	                            onModalWillShow?.();
438	                        }}
439	                        onModalWillHide={onModalWillHide}
440	                        onDismiss={handleDismissModal}
441	                        onSwipeComplete={onClose}
442	                        swipeDirection={swipeDirection}
443	                        shouldPreventScrollOnFocus={shouldPreventScrollOnFocus}
444	                        initialFocus={initialFocus}
445	                        swipeThreshold={swipeThreshold}
446	                        isVisible={isVisible}
447	                        backdropColor={theme.overlay}
448	                        backdropOpacity={backdropOpacityAdjusted}
449	                        backdropTransitionOutTiming={0}
450	                        hasBackdrop={hasBackdrop ?? fullscreen}
451	                        coverScreen={fullscreen}
452	                        style={[modalStyle, sidePanelStyle]}
453	                        deviceHeight={windowHeight}
454	                        deviceWidth={windowWidth}
455	                        // eslint-disable-next-line react/jsx-props-no-spreading
456	                        {...animationInProps}
457	                        animationOut={animationOut ?? modalStyleAnimationOut}
458	                        animationOutTiming={animationOutTiming}
459	                        useNativeDriver={useNativeDriver}
460	                        useNativeDriverForBackdrop={useNativeDriverForBackdrop}
461	                        hideModalContentWhileAnimating={hideModalContentWhileAnimating}
462	                        statusBarTranslucent={statusBarTranslucent}
463	                        navigationBarTranslucent={navigationBarTranslucent}
464	                        onLayout={onLayout}
465	                        avoidKeyboard={avoidKeyboard}
466	                        customBackdrop={shouldUseCustomBackdrop ? <Overlay onPress={handleBackdropPress} /> : undefined}
467	                        type={type}
468	                        shouldUseReanimatedModal={shouldUseReanimatedModal}
469	                        isKeyboardActive={keyboardStateContextValue?.isKeyboardActive}
470	                        saveFocusState={saveFocusState}
471	                    >
472	                        <Animated.View
473	                            onLayout={onViewLayout}
474	                            style={[styles.defaultModalContainer, modalContainerStyle, modalPaddingStyles, !isVisible && styles.pointerEventsNone, sidePanelAnimatedStyle]}
475	                            ref={ref}
476	                        >
477	                            <ColorSchemeWrapper>{children}</ColorSchemeWrapper>
478	                        </Animated.View>
479	                    </ModalComponent>
480	                </View>
481	            </ScreenWrapperOfflineIndicatorContext.Provider>
482	        </ModalContext.Provider>
483	    );
484	}
485	
486	BaseModal.displayName = 'BaseModalWithRef';
487	
488	export default forwardRef(BaseModal);
