17	
18	function ReanimatedModal({
19	    testID,
20	    animationInDelay,
21	    animationInTiming = CONST.MODAL.ANIMATION_TIMING.DEFAULT_IN,
22	    animationOutTiming = CONST.MODAL.ANIMATION_TIMING.DEFAULT_OUT,
23	    animationIn = 'fadeIn',
24	    animationOut = 'fadeOut',
25	    avoidKeyboard = false,
26	    coverScreen = true,
27	    children,
28	    hasBackdrop = true,
29	    backdropColor = 'black',
30	    backdropOpacity = variables.overlayOpacity,
31	    customBackdrop = null,
32	    isVisible = false,
33	    onModalWillShow = noop,
34	    onModalShow = noop,
35	    onModalWillHide = noop,
36	    onModalHide = noop,
37	    onDismiss,
38	    onBackdropPress = noop,
39	    onBackButtonPress = noop,
40	    style,
41	    type,
42	    statusBarTranslucent = false,
43	    onSwipeComplete,
44	    swipeDirection,
45	    swipeThreshold,
46	    shouldPreventScrollOnFocus,
47	    initialFocus,
48	    ...props
49	}: ReanimatedModalProps) {
